using FairyGUI;
using UnityEngine;

namespace Game.UI.Hero
{
    /// <summary>
    /// 英雄列表项绑定器 - 用于HeroList列表中的每个英雄卡片
    /// </summary>
    public class HeroListItemBinder : GComponent
    {
        #region Constants
        private const string CONTROLLER_OWN_STATE = "c1";
        private const string CONTROLLER_QUALITY = "c2";
        private const string TRANSITION_T2 = "t2";

        // 控制器页面索引
        private const int PAGE_OWNED = 0;       // 已获得
        private const int PAGE_NOT_OWNED = 1;   // 未获得
        private const int PAGE_CAN_COMPOSE = 2; // 可合成

        // 品质页面索引
        private const int PAGE_QUALITY_WHITE = 0;
        private const int PAGE_QUALITY_GREEN = 1;
        private const int PAGE_QUALITY_BLUE = 2;
        private const int PAGE_QUALITY_PURPLE = 3;
        private const int PAGE_QUALITY_GOLD = 4;
        private const int PAGE_QUALITY_RED = 5;
        #endregion

        #region Components
        private GComponent _icon;
        private GLoader _loader;
        private GComponent _redPoint;
        private GProgressBar _progressBar;
        private GComponent _upgradeRedPoint;
        private GButton _btnEmpty;
        private GComponent _heroType;
        private GComponent _starsList;
        private GTextField _textCompose;
        private GTextField _textLevel;
        private Transition _transitionT2;
        #endregion

        #region Controllers
        private Controller _ownStateController;
        private Controller _qualityController;
        #endregion

        #region Properties
        public long HeroId { get; private set; }
        public bool IsOwned { get; private set; }
        public bool CanCompose { get; private set; }
        #endregion

        #region Events
        public event System.Action<HeroListItemBinder> OnItemClick;
        #endregion

        #region Lifecycle
        public override void ConstructFromXML(FairyGUI.Utils.XML xml)
        {
            base.ConstructFromXML(xml);

            InitializeComponents();
            InitializeControllers();
            BindEvents();
        }

        private void InitializeComponents()
        {
            // 获取组件引用
            _icon = GetChild("icon") as GComponent;
            _loader = GetChild("n81") as GLoader;
            _redPoint = GetChild("n54") as GComponent;
            _progressBar = GetChild("n63") as GProgressBar;
            _upgradeRedPoint = GetChild("n68") as GComponent;
            _btnEmpty = GetChild("n69") as GButton;
            _heroType = GetChild("n62") as GComponent;
            _starsList = GetChild("n58") as GComponent;
            _textCompose = GetChild("text") as GTextField;
            _textLevel = GetChild("Lv") as GTextField;

            // 获取动效
            _transitionT2 = GetTransition(TRANSITION_T2);
        }

        private void InitializeControllers()
        {
            _ownStateController = GetController(CONTROLLER_OWN_STATE);
            _qualityController = GetController(CONTROLLER_QUALITY);
        }

        private void BindEvents()
        {
            if (_btnEmpty != null)
            {
                _btnEmpty.onClick.Add(OnButtonItemClick);
            }
        }

        public override void Dispose()
        {
            UnbindEvents();
            base.Dispose();
        }

        private void UnbindEvents()
        {
            if (_btnEmpty != null)
            {
                _btnEmpty.onClick.Remove(OnButtonItemClick);
            }
        }
        #endregion

        #region Public Methods
        /// <summary>
        /// 更新英雄数据
        /// </summary>
        public void UpdateData(HeroListData data)
        {
            if (data == null) return;

            HeroId = data.HeroId;
            IsOwned = data.IsOwned;
            CanCompose = data.CanCompose;

            UpdateOwnState(data);
            UpdateQuality(data.Quality);
            UpdateLevel(data.Level);
            UpdateStars(data.StarCount);
            UpdateProgress(data.FragmentCount, data.FragmentNeed);
            UpdateRedPoint(data.HasRedPoint);
            UpdateIcon(data.IconUrl);
        }

        /// <summary>
        /// 设置选中状态
        /// </summary>
        public void SetSelected(bool selected)
        {
            // 可扩展选中效果
        }

        /// <summary>
        /// 播放开启动效
        /// </summary>
        public void PlayEnterAnimation()
        {
            _transitionT2?.Play();
        }
        #endregion

        #region Private Methods
        private void UpdateOwnState(HeroListData data)
        {
            if (_ownStateController == null) return;

            if (data.IsOwned)
            {
                _ownStateController.selectedIndex = PAGE_OWNED;
            }
            else if (data.CanCompose)
            {
                _ownStateController.selectedIndex = PAGE_CAN_COMPOSE;
            }
            else
            {
                _ownStateController.selectedIndex = PAGE_NOT_OWNED;
            }
        }

        private void UpdateQuality(HeroQuality quality)
        {
            if (_qualityController == null) return;

            int pageIndex = quality switch
            {
                HeroQuality.White => PAGE_QUALITY_WHITE,
                HeroQuality.Green => PAGE_QUALITY_GREEN,
                HeroQuality.Blue => PAGE_QUALITY_BLUE,
                HeroQuality.Purple => PAGE_QUALITY_PURPLE,
                HeroQuality.Gold => PAGE_QUALITY_GOLD,
                HeroQuality.Red => PAGE_QUALITY_RED,
                _ => PAGE_QUALITY_WHITE
            };

            _qualityController.selectedIndex = pageIndex;
        }

        private void UpdateLevel(int level)
        {
            if (_textLevel != null)
            {
                _textLevel.text = $"Lv.{level}";
            }
        }

        private void UpdateStars(int starCount)
        {
            // 星级组件由 fiveStarsList 处理
            // 可通过子组件接口设置星级
        }

        private void UpdateProgress(int current, int need)
        {
            if (_progressBar == null || need <= 0) return;

            _progressBar.max = need;
            _progressBar.value = current;
        }

        private void UpdateRedPoint(bool show)
        {
            if (_redPoint != null)
            {
                _redPoint.visible = show;
            }
        }

        private void UpdateIcon(string iconUrl)
        {
            if (string.IsNullOrEmpty(iconUrl)) return;

            // 设置英雄头像
            // 通过 hero_ bust 组件设置
        }
        #endregion

        #region Event Handlers
        private void OnButtonItemClick()
        {
            OnItemClick?.Invoke(this);
        }
        #endregion
    }
}

using FairyGUI;
using System.Collections.Generic;
using UnityEngine;

namespace Game.UI.Hero
{
    /// <summary>
    /// 英雄列表界面绑定器 - 管理英雄列表展示
    /// </summary>
    public class HeroListBinder : GComponent
    {
        #region Constants
        private const string PACKAGE_NAME = "601_NewHero";
        private const string COMPONENT_NAME = "HeroList";
        private const string TRANSITION_DYNAMIC_ON = "DynamicON";

        // 列表配置
        private const int LIST_COLUMN_COUNT = 4;
        private const int LIST_LINE_GAP = 5;
        private const int LIST_COL_GAP = 32;
        #endregion

        #region Serialized Fields (通过FGUI编辑器配置)
        // 背景元素
        private GImage _bgImage;
        private GImage _contentBg;

        // 顶部栏
        private GComponent _headline;

        // 英雄列表
        private GList _heroList;

        // 底部按钮组
        private GGroup _buttonGroup;
        private GButton _btnLegion;
        private GButton _btnRecruit;

        // 动效
        private Transition _transitionDynamicOn;
        #endregion

        #region Private Fields
        private readonly List<HeroListData> _heroDataList = new List<HeroListData>();
        private readonly Dictionary<long, HeroListItemBinder> _heroItemMap = new Dictionary<long, HeroListItemBinder>();
        private int _currentSelectedIndex = -1;
        private HeroListData _currentSelectedHero;
        #endregion

        #region Properties
        public int HeroCount => _heroDataList.Count;
        public HeroListData CurrentSelectedHero => _currentSelectedHero;
        public GList HeroList => _heroList;
        #endregion

        #region Events
        public event System.Action<HeroListData> OnHeroItemSelected;
        public event System.Action OnRecruitButtonClick;
        public event System.Action OnLegionButtonClick;
        public event System.Action OnBackButtonClick;
        #endregion

        #region Lifecycle
        public override void ConstructFromXML(FairyGUI.Utils.XML xml)
        {
            base.ConstructFromXML(xml);

            InitializeComponents();
            BindEvents();
        }

        private void InitializeComponents()
        {
            // 获取背景元素
            _bgImage = GetChild("n5") as GImage;
            _contentBg = GetChild("n6") as GImage;

            // 获取顶部栏
            _headline = GetChild("headline") as GComponent;

            // 获取英雄列表
            _heroList = GetChild("n1") as GList;
            if (_heroList != null)
            {
                _heroList.itemRenderer = OnRenderListItem;
                _heroList.onClickItem.Add(OnListItemClick);
            }

            // 获取底部按钮组
            _buttonGroup = GetChild("n4") as GGroup;
            _btnLegion = GetChild("n2") as GButton;
            _btnRecruit = GetChild("n3") as GButton;

            // 获取动效
            _transitionDynamicOn = GetTransition(TRANSITION_DYNAMIC_ON);
        }

        private void BindEvents()
        {
            if (_btnRecruit != null)
            {
                _btnRecruit.onClick.Add(OnBtnRecruitClick);
            }

            if (_btnLegion != null)
            {
                _btnLegion.onClick.Add(OnBtnLegionClick);
            }

            // 绑定顶部栏返回按钮
            if (_headline != null)
            {
                var btnReturn = _headline.GetChild("btn_return") as GButton;
                if (btnReturn != null)
                {
                    btnReturn.onClick.Add(OnBtnBackClick);
                }
            }
        }

        public override void Dispose()
        {
            Cleanup();
            base.Dispose();
        }

        private void Cleanup()
        {
            UnbindEvents();
            ClearHeroList();
        }

        private void UnbindEvents()
        {
            if (_heroList != null)
            {
                _heroList.onClickItem.Remove(OnListItemClick);
            }

            if (_btnRecruit != null)
            {
                _btnRecruit.onClick.Remove(OnBtnRecruitClick);
            }

            if (_btnLegion != null)
            {
                _btnLegion.onClick.Remove(OnBtnLegionClick);
            }
        }
        #endregion

        #region Public Methods
        /// <summary>
        /// 设置标题文本
        /// </summary>
        public void SetTitle(string title)
        {
            if (_headline == null) return;

            var titleText = _headline.GetChild("title") as GTextField;
            if (titleText != null)
            {
                titleText.text = title;
            }
        }

        /// <summary>
        /// 刷新英雄列表数据
        /// </summary>
        public void RefreshHeroList(List<HeroListData> heroList)
        {
            if (heroList == null || _heroList == null) return;

            _heroDataList.Clear();
            _heroDataList.AddRange(heroList);

            _heroList.numItems = _heroDataList.Count;
            _heroList.ResizeToFit(_heroDataList.Count);
        }

        /// <summary>
        /// 添加单个英雄到列表
        /// </summary>
        public void AddHero(HeroListData heroData)
        {
            if (heroData == null) return;

            _heroDataList.Add(heroData);
            if (_heroList != null)
            {
                _heroList.numItems = _heroDataList.Count;
            }
        }

        /// <summary>
        /// 移除指定英雄
        /// </summary>
        public void RemoveHero(long heroId)
        {
            int index = _heroDataList.FindIndex(h => h.HeroId == heroId);
            if (index >= 0)
            {
                _heroDataList.RemoveAt(index);
                _heroItemMap.Remove(heroId);

                if (_heroList != null)
                {
                    _heroList.numItems = _heroDataList.Count;
                }
            }
        }

        /// <summary>
        /// 更新指定英雄数据
        /// </summary>
        public void UpdateHero(HeroListData heroData)
        {
            if (heroData == null) return;

            int index = _heroDataList.FindIndex(h => h.HeroId == heroData.HeroId);
            if (index >= 0)
            {
                _heroDataList[index] = heroData;

                if (_heroItemMap.TryGetValue(heroData.HeroId, out var item))
                {
                    item.UpdateData(heroData);
                }
            }
        }

        /// <summary>
        /// 选中指定英雄
        /// </summary>
        public void SelectHero(long heroId)
        {
            int index = _heroDataList.FindIndex(h => h.HeroId == heroId);
            if (index >= 0)
            {
                SelectHeroByIndex(index);
            }
        }

        /// <summary>
        /// 选中指定索引的英雄
        /// </summary>
        public void SelectHeroByIndex(int index)
        {
            if (index < 0 || index >= _heroDataList.Count) return;

            _currentSelectedIndex = index;
            _currentSelectedHero = _heroDataList[index];

            if (_heroList != null)
            {
                _heroList.selectedIndex = index;
            }

            OnHeroItemSelected?.Invoke(_currentSelectedHero);
        }

        /// <summary>
        /// 设置招募按钮可见性
        /// </summary>
        public void SetRecruitButtonVisible(bool visible)
        {
            if (_btnRecruit != null)
            {
                _btnRecruit.visible = visible;
            }
        }

        /// <summary>
        /// 设置军团按钮可见性
        /// </summary>
        public void SetLegionButtonVisible(bool visible)
        {
            if (_btnLegion != null)
            {
                _btnLegion.visible = visible;
            }
        }

        /// <summary>
        /// 播放界面开启动效
        /// </summary>
        public void PlayEnterAnimation()
        {
            _transitionDynamicOn?.Play();
        }

        /// <summary>
        /// 滚动到指定英雄
        /// </summary>
        public void ScrollToHero(long heroId, bool anim = true)
        {
            int index = _heroDataList.FindIndex(h => h.HeroId == heroId);
            if (index >= 0 && _heroList != null)
            {
                _heroList.ScrollToView(index, anim, false);
            }
        }

        /// <summary>
        /// 清空列表
        /// </summary>
        public void ClearHeroList()
        {
            _heroDataList.Clear();
            _heroItemMap.Clear();
            _currentSelectedIndex = -1;
            _currentSelectedHero = null;

            if (_heroList != null)
            {
                _heroList.numItems = 0;
            }
        }
        #endregion

        #region Private Methods
        private void OnRenderListItem(int index, GObject obj)
        {
            if (index < 0 || index >= _heroDataList.Count) return;

            var item = obj as HeroListItemBinder;
            if (item == null) return;

            var data = _heroDataList[index];
            item.UpdateData(data);

            // 更新缓存
            if (_heroItemMap.ContainsKey(data.HeroId))
            {
                _heroItemMap[data.HeroId] = item;
            }
            else
            {
                _heroItemMap.Add(data.HeroId, item);
            }

            // 绑定点击事件
            item.OnItemClick -= OnHeroItemClick;
            item.OnItemClick += OnHeroItemClick;
        }
        #endregion

        #region Event Handlers
        private void OnListItemClick(EventContext context)
        {
            var item = context.data as HeroListItemBinder;
            if (item == null) return;

            int index = _heroList.GetChildIndex(item);
            SelectHeroByIndex(index);
        }

        private void OnHeroItemClick(HeroListItemBinder item)
        {
            if (item == null) return;

            int index = _heroList.GetChildIndex(item);
            SelectHeroByIndex(index);
        }

        private void OnBtnRecruitClick()
        {
            OnRecruitButtonClick?.Invoke();
        }

        private void OnBtnLegionClick()
        {
            OnLegionButtonClick?.Invoke();
        }

        private void OnBtnBackClick()
        {
            OnBackButtonClick?.Invoke();
        }
        #endregion
    }
}

using System;

namespace Game.UI.Hero
{
    /// <summary>
    /// 英雄品质枚举
    /// </summary>
    public enum HeroQuality
    {
        White = 0,
        Green = 1,
        Blue = 2,
        Purple = 3,
        Gold = 4,
        Red = 5
    }

    /// <summary>
    /// 英雄列表数据模型
    /// </summary>
    [Serializable]
    public class HeroListData
    {
        /// <summary>
        /// 英雄唯一ID
        /// </summary>
        public long HeroId;

        /// <summary>
        /// 英雄配置ID
        /// </summary>
        public int ConfigId;

        /// <summary>
        /// 英雄名称
        /// </summary>
        public string Name;

        /// <summary>
        /// 英雄等级
        /// </summary>
        public int Level;

        /// <summary>
        /// 星级数量 (1-5)
        /// </summary>
        public int StarCount;

        /// <summary>
        /// 英雄品质
        /// </summary>
        public HeroQuality Quality;

        /// <summary>
        /// 英雄类型 (战士/法师/射手等)
        /// </summary>
        public int HeroType;

        /// <summary>
        /// 头像图标URL
        /// </summary>
        public string IconUrl;

        /// <summary>
        /// 半身像URL
        /// </summary>
        public string BustUrl;

        /// <summary>
        /// 是否已获得
        /// </summary>
        public bool IsOwned;

        /// <summary>
        /// 是否可合成
        /// </summary>
        public bool CanCompose;

        /// <summary>
        /// 当前碎片数量
        /// </summary>
        public int FragmentCount;

        /// <summary>
        /// 合成所需碎片数量
        /// </summary>
        public int FragmentNeed;

        /// <summary>
        /// 是否有红点提示
        /// </summary>
        public bool HasRedPoint;

        /// <summary>
        /// 战斗力
        /// </summary>
        public long CombatPower;

        /// <summary>
        /// 排序权重
        /// </summary>
        public int SortWeight;

        /// <summary>
        /// 创建默认的英雄数据
        /// </summary>
        public static HeroListData CreateDefault(long heroId, string name)
        {
            return new HeroListData
            {
                HeroId = heroId,
                Name = name,
                Level = 1,
                StarCount = 1,
                Quality = HeroQuality.White,
                IsOwned = true,
                FragmentCount = 0,
                FragmentNeed = 30,
                HasRedPoint = false,
                SortWeight = 0
            };
        }

        /// <summary>
        /// 获取碎片进度百分比
        /// </summary>
        public float GetFragmentProgress()
        {
            if (FragmentNeed <= 0) return 0f;
            return (float)FragmentCount / FragmentNeed;
        }
    }
}

using FairyGUI;
using System.Collections.Generic;
using UnityEngine;

namespace Game.UI.Hero
{
    /// <summary>
    /// 英雄列表界面控制器 - 处理界面逻辑和数据交互
    /// </summary>
    public class HeroListController : MonoBehaviour
    {
        #region Constants
        private const string PACKAGE_NAME = "601_NewHero";
        private const string COMPONENT_NAME = "HeroList";
        private const string DEFAULT_TITLE = "英雄列表";
        #endregion

        #region Serialized Fields
        [Header("UI Settings")]
        [SerializeField] private string _packageName = PACKAGE_NAME;
        [SerializeField] private string _componentName = COMPONENT_NAME;
        [SerializeField] private bool _showLegionButton = false;
        #endregion

        #region Private Fields
        private GComponent _mainView;
        private HeroListBinder _binder;
        private readonly List<HeroListData> _heroDataCache = new List<HeroListData>();
        private bool _isInitialized = false;
        #endregion

        #region Properties
        public HeroListBinder Binder => _binder;
        public bool IsVisible => _mainView != null && _mainView.onStage;
        #endregion

        #region Events
        public event System.Action<HeroListData> OnHeroSelected;
        public event System.Action OnRecruitClicked;
        public event System.Action OnLegionClicked;
        public event System.Action OnClosed;
        #endregion

        #region Unity Lifecycle
        private void Awake()
        {
            InitializeComponents();
        }

        private void OnDestroy()
        {
            Cleanup();
        }
        #endregion

        #region Public Methods
        /// <summary>
        /// 显示界面
        /// </summary>
        public void Show()
        {
            if (!_isInitialized)
            {
                InitializeComponents();
            }

            if (_mainView == null) return;

            _mainView.visible = true;
            _mainView.MakeFullScreen();
            GRoot.inst.AddChild(_mainView);

            PlayEnterAnimation();
        }

        /// <summary>
        /// 隐藏界面
        /// </summary>
        public void Hide()
        {
            if (_mainView == null) return;

            _mainView.RemoveFromParent();
            _mainView.visible = false;
        }

        /// <summary>
        /// 关闭界面
        /// </summary>
        public void Close()
        {
            Hide();
            OnClosed?.Invoke();
        }

        /// <summary>
        /// 刷新英雄列表
        /// </summary>
        public void RefreshHeroList(List<HeroListData> heroList)
        {
            if (_binder == null) return;

            _heroDataCache.Clear();
            if (heroList != null)
            {
                _heroDataCache.AddRange(heroList);
            }

            _binder.RefreshHeroList(_heroDataCache);
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        public void SetTitle(string title)
        {
            _binder?.SetTitle(title);
        }

        /// <summary>
        /// 选中指定英雄
        /// </summary>
        public void SelectHero(long heroId)
        {
            _binder?.SelectHero(heroId);
        }

        /// <summary>
        /// 更新单个英雄数据
        /// </summary>
        public void UpdateHero(HeroListData heroData)
        {
            _binder?.UpdateHero(heroData);
        }

        /// <summary>
        /// 设置招募按钮可见性
        /// </summary>
        public void SetRecruitButtonVisible(bool visible)
        {
            _binder?.SetRecruitButtonVisible(visible);
        }

        /// <summary>
        /// 设置军团按钮可见性
        /// </summary>
        public void SetLegionButtonVisible(bool visible)
        {
            _binder?.SetLegionButtonVisible(visible);
        }
        #endregion

        #region Private Methods
        private void InitializeComponents()
        {
            if (_isInitialized) return;

            // 加载包
            UIPackage.AddPackage(_packageName);

            // 创建主视图
            _mainView = UIPackage.CreateObject(_packageName, _componentName) as GComponent;
            if (_mainView == null)
            {
                Debug.LogError($"[HeroListController] Failed to create component: {_componentName}");
                return;
            }

            _mainView.MakeFullScreen();

            // 获取绑定器
            _binder = _mainView as HeroListBinder;
            if (_binder == null)
            {
                Debug.LogWarning("[HeroListController] HeroListBinder not found, using generic GComponent");
            }

            // 绑定事件
            BindEvents();

            // 初始化按钮状态
            InitializeButtonStates();

            _isInitialized = true;
        }

        private void BindEvents()
        {
            if (_binder == null) return;

            _binder.OnHeroItemSelected += HandleHeroSelected;
            _binder.OnRecruitButtonClick += HandleRecruitClick;
            _binder.OnLegionButtonClick += HandleLegionClick;
            _binder.OnBackButtonClick += HandleBackClick;
        }

        private void UnbindEvents()
        {
            if (_binder == null) return;

            _binder.OnHeroItemSelected -= HandleHeroSelected;
            _binder.OnRecruitButtonClick -= HandleRecruitClick;
            _binder.OnLegionButtonClick -= HandleLegionClick;
            _binder.OnBackButtonClick -= HandleBackClick;
        }

        private void InitializeButtonStates()
        {
            if (_binder != null)
            {
                _binder.SetLegionButtonVisible(_showLegionButton);
            }
        }

        private void PlayEnterAnimation()
        {
            _binder?.PlayEnterAnimation();
        }

        private void Cleanup()
        {
            UnbindEvents();

            if (_mainView != null)
            {
                _mainView.Dispose();
                _mainView = null;
            }

            _binder = null;
            _isInitialized = false;
        }
        #endregion

        #region Event Handlers
        private void HandleHeroSelected(HeroListData heroData)
        {
            if (heroData == null) return;

            Debug.Log($"[HeroListController] Hero selected: {heroData.Name} (ID: {heroData.HeroId})");
            OnHeroSelected?.Invoke(heroData);
        }

        private void HandleRecruitClick()
        {
            Debug.Log("[HeroListController] Recruit button clicked");
            OnRecruitClicked?.Invoke();
        }

        private void HandleLegionClick()
        {
            Debug.Log("[HeroListController] Legion button clicked");
            OnLegionClicked?.Invoke();
        }

        private void HandleBackClick()
        {
            Close();
        }
        #endregion

        #region Static Factory Methods
        /// <summary>
        /// 创建英雄列表界面实例
        /// </summary>
        public static HeroListController Create(Transform parent = null)
        {
            var go = new GameObject("HeroListController");
            if (parent != null)
            {
                go.transform.SetParent(parent, false);
            }

            var controller = go.AddComponent<HeroListController>();
            return controller;
        }
        #endregion
    }
}

