using System;
using System.Reflection;
using System.Collections.Generic;
using UnityEngine;
using FairyGUI;
using System.Collections;

namespace DayZ
{
    /// <summary>
    /// UI基类
    /// UI全部通过static create动态创建出来，暂不支持直接放在场景中，如果预加载也是代码动态创建
    /// PopupBaseView的生命周期是 Awake OnEnable Init Open Start
    /// </summary>
    public class PopupBaseView : MonoBehaviour
    {
        /// <summary>
        /// 该函数还在测试阶段，适当可以使用看看
        /// </summary>
        protected void InitComponentsWithAttributes()
        {
            foreach (var field in this.GetType().GetFields(BindingFlags.NonPublic | BindingFlags.Instance))
            {
                if (FariyGUIAttributeHelper.GetTextField(_mainView, field, (textField, attr) =>
                {
                    if (!string.IsNullOrEmpty(attr.TextID))
                        textField.text = Global._lang(attr.TextID);
                    field.SetValue(this, textField);
                }))
                    continue;
                if (FariyGUIAttributeHelper.GetTextInput(_mainView, field, (textInput, attr) =>
                {
                    textInput.promptText = Global._lang(attr.PromptTextID);
                    textInput.text = string.IsNullOrEmpty(attr.TextID) ? string.Empty : Global._lang(attr.TextID);
                    field.SetValue(this, textInput);
                }))
                    continue;
                if (FariyGUIAttributeHelper.GetButton(_mainView, field, (button, attr) =>
                {
                    if (!string.IsNullOrEmpty(attr.TitleID))
                        button.title = Global._lang(attr.TitleID);

                    var method = this.GetType().GetMethod(attr.Method, BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
                    button.onClick.Add(() => method.Invoke(this, new object[0]));
                    field.SetValue(this, button);
                }))
                    continue;
                if (FariyGUIAttributeHelper.GetController(_mainView, field, (controller, attr) =>
                {
                    field.SetValue(this, controller);
                }))
                    continue;
            }
        }

        public GComponent _mainView;
        private string className;
        protected GTextField _title;
        protected GButton _helpBtn;

        public GButton returnBtn;
        public GButton closeBtn;
        public GButton returnBtn1;
        public GButton returnBtn2;
        public bool canClose
        {
            get;
            set;
        } = true;
        protected GObject frame;


        public List<PopupBaseView> shotOfView = new List<PopupBaseView>();

        public bool needBlur;
        RenderTexture shotTexture;
        public GImage blurBGNew;//静态截图模糊使用Gimage作为载体
        public GGraph blurBGOld;//实时模糊使用ggraph作为载体

        private List<string> packageList = new List<string>();



        public string ClassName
        {
            set { className = value; }

            get { return className; }
        }

        private TypeWriterTool _typeWriter;

        public TypeWriterTool m_typeWriter
        {
            get
            {
                if (_typeWriter == null)
                {
                    _typeWriter = this.gameObject.AddComponent<TypeWriterTool>();
                }
                return _typeWriter;
            }
        }


        /// <summary>
        /// 以前的Preload可以放在awake里面
        /// </summary>
        protected virtual void Awake()
        {
            //为通用的组件设置扩展类
            UIObjectFactory.SetPackageItemExtension("ui://072_Recover/quality_soldier", typeof(SoldierBackGroundColor));
            UIObjectFactory.SetPackageItemExtension("ui://Store/buy_count", typeof(GoldExchangeTimes));
        }

        /// <summary>
        /// 一些回调的注册可以放在OnEnable里面
        /// </summary>
        protected virtual void OnEnable()
        {

        }


        protected virtual void OnDisable()
        {
            if (!PopupViewController.getInstance().CheckViewInBlackList(this))
                PopupViewController.getInstance().ResetAllPopupViews();
            RemoveBlurList(blurBGOld);
        }

        /// <summary>
        /// 这里主要用来解析外部传进来的参数，但记得base.Init
        /// </summary>
        public virtual void Init(params object[] data)
        {
            Transition trans = _mainView.GetTransition("DynamicON");
            if (trans != null)
            {
                //LogCommon.LogError("DynamicON");
                trans.Play();
            }
        }
        /// <summary>
        /// 获取Fairygui组件和注册监听事件
        /// </summary>
        public virtual void InitializeFairyComponents()
        {
            _mainView = this.GetComponent<UIPanel>().ui;
            GLabel headline = _mainView.GetChild("headline") as GLabel;
            if (headline != null)
            {
                returnBtn = headline.GetChild("btn_return") as GButton;
                if (returnBtn != null)
                    returnBtn.onClick.Add(Return_OnClick);
                closeBtn = headline.GetChild("btn_close") as GButton;
                if (closeBtn != null)
                    closeBtn.onClick.Add(Close_OnClick);
                _title = headline.GetChild("title") as GTextField;
                _helpBtn = headline.GetChild("btn_details") as GButton;
            }
            returnBtn1 = _mainView.GetChild("btn_return") as GButton;
            if (returnBtn1 != null)
                returnBtn1.onClick.Add(Return_OnClick);
            if (_title == null)
                _title = _mainView.GetChild("title") as GTextField;

            var m_bgCloseObj = this._mainView.GetChild("backgroundCollider") as GButton;
            if (m_bgCloseObj != null)
            {
                returnBtn2 = m_bgCloseObj;// as GButton;
                returnBtn2.onClick.Add(onBackgroundCloseClick);
            }

        }


        public GObject GetReturnBtn()
        {
            if (returnBtn != null)
            {
                return returnBtn;
            }
            if (returnBtn1 != null)
            {
                return returnBtn1;
            }
            return null;
        }


        /// <summary>
        /// 界面打开时候的一些逻辑
        /// </summary>
        public virtual void Open()
        {
            initBlurLayer();
        }

        /// <summary>
        /// FairGUI的Getchild写在Start里面，不要写在awake或者OnEnablel里面
        /// </summary>
        protected virtual void Start()
        { }

        protected virtual void Update()
        {

        }

        /// <summary>
        /// 界面关闭时候的一些逻辑
        /// 有其它需求在自己的UI类里复写这个函数
        /// </summary>
        public virtual void Close()
        {
            if (_typeWriter != null)
                _typeWriter.Reset();

            if (PopupViewController.getInstance().afterUIComViews.Contains(this))
            {
                PopupViewController.getInstance().afterUIComViews.Remove(this);
            }
            shotOfView.Clear();
            ClearBlurTexture();
            if (this is IReusePanel)
            {
                this.gameObject.SetActive(false);
                this.ClearBlurBg();
                (this as IReusePanel).Reset();
            }
            else
            {
                try
                {
                    DestroyImmediate(gameObject);
                }
                catch (Exception)
                {

                }
            }
        }

        public virtual void onBackgroundCloseClick(EventContext context)
        {
            if (CCCommonUtils.checkIsOpenByKey("NewSoundEffect"))
            {
                SoundController.sharedSound().playEffects(Global.Music_Effect_UI_BUTTON_RETURN);
            }
            else
            {
                SoundController.sharedSound().playEffects(Global.Music_Sfx_return_button);
            }
            closeSelf();
        }

        public void closeSelf()
        {
            if (!canClose)
                return;
            Transition trans = _mainView.GetTransition("DynamicOff");
            if (trans != null)
            {
                trans.Play(() =>
                {
                    PopupViewController.getInstance().ClosePopupView(className);
                });
            }
            else
            {
                PopupViewController.getInstance().ClosePopupView(className);
            }
        }

        public virtual void Return_OnClick()
        {
            if (CCCommonUtils.checkIsOpenByKey("NewSoundEffect"))
            {
                SoundController.sharedSound().playEffects(Global.Music_Effect_UI_BUTTON_RETURN);
            }
            else
            {
                SoundController.sharedSound().playEffects(Global.Music_Sfx_return_button);
            }
            closeSelf();
        }

        public virtual void Close_OnClick()
        {
            if (CCCommonUtils.checkIsOpenByKey("NewSoundEffect"))
            {
                SoundController.sharedSound().playEffects(Global.Music_Effect_UI_BUTTON_RETURN);
            }
            else
            {
                SoundController.sharedSound().playEffects(Global.Music_Sfx_return_button);
            }
            Transition trans = _mainView.GetTransition("DynamicOff");
            if (trans != null)
            {
                trans.Play(() =>
                {
                    PopupViewController.getInstance().removeAllPopupView();
                });
            }
            else
            {
                PopupViewController.getInstance().removeAllPopupView();
            }
        }

        public void setCommonToTitelText(string title)
        {
            if (_title != null)
            {
                _title.text = title;
            }
        }

        public bool isTouchInside(GObject target, EventContext context)
        {
            return Global.isTouchInside(target, context);
        }


        public void setTitleName(string _name)
        {
            if (_title != null)
            {
                _title.text = _name;
            }
        }

        public virtual void KeyBack_OnClick()
        {
            closeSelf();
        }

        /// <summary>
        /// 获取节点
        /// 添加日志
        /// </summary>
        /// <param name="name"></param>
        /// <returns></returns>
        public GObject getChild(string name)
        {
            return _mainView.getChild(name);
        }
        /// <summary>
        /// 获取控制器
        /// 添加日志
        /// </summary>
        /// <param name="name"></param>
        /// <returns></returns>
        public Controller getController(string name)
        {
            return _mainView.getController(name);
        }

        #region 适配cocos以前的逻辑暂不处理
        protected int m_topUiType; public int getTopUiType() { return m_topUiType; }
        public void setTopUiType(int var) { m_topUiType = var; }
        protected bool m_isSystemMail; public bool getIsSystemMail() { return m_isSystemMail; }
        public void setIsSystemMail(bool var) { m_isSystemMail = var; }
        protected bool m_isDetectMailFromAndroid; public bool getIsDetectMailFromAndroid() { return m_isDetectMailFromAndroid; }
        public void setIsDetectMailFromAndroid(bool var) { m_isDetectMailFromAndroid = var; }

        public string getTypeName()
        {
            throw new NotImplementedException();
        }

        protected virtual bool init()
        {
            return false;
        }

        public virtual void onExit()
        {

        }
        public virtual void onEnter()
        {

        }

        /// <summary>
        /// 设置是否有虚化背景
        /// </summary>
        /// <param name="need"></param>
        public void SetNeedBlur(bool need)
        {
            needBlur = need;
        }

        /// <summary>
        /// 添加虚化背景
        /// </summary>
        public void initBlurLayer()
        {
            if (needBlur)//后期需要加表
            {
                if (!UIComponent.IsInstanceExist())
                {
                    return;
                }
                CCSafeNotificationCenter.sharedNotificationCenter().postNotification(Global.MSG_POPUP_VIEW_INITBLUR);
                if (!CCCommonUtils.needBlur())
                {
                    return;
                }
                createBackBlurSprite();
            }
        }

        /// <summary>
        /// 已存在的虚化背景列表，只显示最后一个
        /// </summary>
        public static List<GObject> graphs = new List<GObject>();

        /// <summary>
        /// 往列表里添加一个虚化背景组件，刷新显示
        /// </summary>
        /// <param name="graph"></param>
        public static void AddBlurList(GObject graph)
        {
            if (PopupViewController.getInstance().useStaticBlur)
                return;
            if (!graphs.Contains(graph))
            {
                graphs.Add(graph);
            }
            CheckBlurSprite();
        }

        /// <summary>
        /// 从列表里删除一个虚化背景组件，刷新显示
        /// </summary>
        /// <param name="graph"></param>
        public static void RemoveBlurList(GObject graph)
        {
            if (PopupViewController.getInstance().useStaticBlur)
                return;
            if (graph != null)
            {
                graphs.Remove(graph);
                CheckBlurSprite();
            }
        }


        private static void CheckBlurSprite()
        {
            List<int> nul = new List<int>();
            for (int i = graphs.Count - 1; i >= 0; i--)
            {
                if (graphs[i] == null)
                {
                    nul.Add(i);
                }
            }
            foreach (var it in nul)//删除空的背景
            {
                graphs.RemoveAt(it);
            }
            for (int i = 0; i < graphs.Count; i++)//显示最后一个虚化组件
            {
                graphs[i].setVisible(i == graphs.Count - 1);
            }
        }


        /// <summary>
        /// 创建虚化背景组件
        /// </summary>
        /// <param name="father"></param>
        public void createBackBlurSprite()
        {
            if (!PopupViewController.getInstance().useStaticBlur)
            {
                getScreenShotBlurBgOld();
            }
            //StartCoroutine(getScreenShotBlurBgNewTexture());
            //getScreenShotBlurBgNewRenderTexture();
        }


        //第一版
        //下载的shader，添加一个空白图形背景，对该背景虚化模糊，实时渲染，背景后object可动态展示
        void getScreenShotBlurBgOld()
        {
            if (blurBGOld == null)
            {
                GGraph graph = new GGraph();
                this._mainView.AddChildAt(graph, 0);
                graph.setPosition(Vector2.zero);

                graph.DrawRect(this._mainView.width, this._mainView.height, 1, Color.black, new Color32(10, 10, 10, 128));

                if (PopupViewController.getInstance().deviceLevel != NativeCode.DEVICE_LEVEL.LOW)
                {
                    Material material = Resources.Load<Material>("MaskUIBlurMaterial");
                    graph.displayObject.material = material;
                }

                blurBGOld = graph;
            }
            AddBlurList(blurBGOld);
        }


        //第二版
        //使用截屏，texture2D读取屏幕固定区域像素，再对截屏做一次模糊虚化渲染。
        //但该方式使用texture2D.ReadPixels时要求时机不能在渲染帧，所以取到的图片会有延时，会存在把要打开的界面也截出来
        IEnumerator getScreenShotBlurBgNewTexture()
        {
            yield return new WaitForEndOfFrame();

            Texture2D texture = new Texture2D((int)(StageCamera.main.rect.width * Screen.width), (int)(StageCamera.main.rect.height * Screen.height), TextureFormat.RGB24, false);
            var re = new Rect(StageCamera.main.rect.x * Screen.width, StageCamera.main.rect.y * Screen.height, StageCamera.main.rect.width * Screen.width, StageCamera.main.rect.height * Screen.height);
            texture.ReadPixels(re, 0, 0);
            texture.Apply();


            GImage graph = new GImage();
            this._mainView.AddChildAt(graph, 0);
            graph.texture = new NTexture(texture);

            //调整宽屏时，截到的图片大小
            if ((float)Screen.width / Screen.height > 9f / 16)
            {
                var _scale = 1920f / Screen.height;
                graph.displayObject.gameObject.transform.localScale = new Vector3(_scale, _scale, 1);
            }

            BlurFilter filter = new BlurFilter(graph);
            graph.filter = filter;
            filter.blurSize = 0.015f;
        }

        public void AddBlurBg(RenderTexture texture)
        {
            shotTexture = texture;
            blurBGNew = new GImage();
            this._mainView.AddChildAt(blurBGNew, 0);
            blurBGNew.setPosition(Vector2.zero);
            blurBGNew.SetSize(GRoot.inst.width * ScreenAdaptation.cameraRect.width,
                GRoot.inst.height * ScreenAdaptation.cameraRect.height);
            blurBGNew.AddRelation(this._mainView, RelationType.Size);
            blurBGNew.texture = new NTexture(shotTexture);
        }


        public void ClearBlurBg()
        {
            if (blurBGNew != null)
            {
                blurBGNew.Dispose();
                blurBGNew = null;
            }
            ClearBlurTexture();
        }

        void ClearBlurTexture()
        {
            if (shotTexture != null)
            {
                RenderTexture.ReleaseTemporary(shotTexture);
            }
        }

        #endregion
    }
}

