   417→
   418→### 协程最佳实践
   419→
   420→```csharp
   421→// ✅ 正确：缓存 WaitForSeconds
   422→public class CooldownSystem : MonoBehaviour
   423→{
   424→    private static readonly WaitForSeconds WaitOneSecond = new WaitForSeconds(1f);
   425→    private static readonly WaitForSeconds WaitPointOne = new WaitForSeconds(0.1f);
   426→
   427→    private Coroutine _cooldownCoroutine;
   428→
   429→    public void StartCooldown(float duration)
   430→    {
   431→        if (_cooldownCoroutine != null)
   432→        {
   433→            StopCoroutine(_cooldownCoroutine);
   434→        }
   435→        _cooldownCoroutine = StartCoroutine(CooldownRoutine(duration));
   436→    }
   437→
   438→    private IEnumerator CooldownRoutine(float duration)
   439→    {
   440→        float elapsed = 0f;
   441→        while (elapsed < duration)
   442→        {
   443→            elapsed += Time.deltaTime;
   444→            yield return null;
   445→        }
   446→        OnCooldownComplete();
   447→    }
   448→}
   449→
   450→// ❌ 错误：每次创建新的 WaitForSeconds
