   470→        }
   471→        catch (OperationCanceledException)
   472→        {
   473→            // 处理取消
   474→        }
   475→    }
   476→
   477→    private void OnDestroy()
   478→    {
   479→        _cts?.Cancel();
   480→        _cts?.Dispose();
   481→    }
   482→
   483→    private async Task LoadSceneAsync(string sceneName, CancellationToken token)
   484→    {
   485→        var operation = SceneManager.LoadSceneAsync(sceneName);
   486→        while (!operation.isDone)
   487→        {
   488→            token.ThrowIfCancellationRequested();
   489→            await Task.Yield();
