   537→## 对象池规范
   538→
   539→### 通用对象池实现
   540→
   541→```csharp
   542→public class ObjectPool<T> where T : Component
   543→{
   544→    private readonly Queue<T> _pool = new Queue<T>();
   545→    private readonly T _prefab;
   546→    private readonly Transform _parent;
   547→    private readonly int _initialSize;
   548→
   549→    public ObjectPool(T prefab, Transform parent, int initialSize = 10)
   550→    {
   551→        _prefab = prefab;
   552→        _parent = parent;
   553→        _initialSize = initialSize;
   554→
   555→        Preallocate();
   556→    }
   557→
   558→    private void Preallocate()
   559→    {
   560→        for (int i = 0; i < _initialSize; i++)
   561→        {
   562→            var obj = CreateNew();
   563→            obj.gameObject.SetActive(false);
   564→            _pool.Enqueue(obj);
   565→        }
   566→    }
   567→
   568→    public T Get()
   569→    {
   570→        T obj = _pool.Count > 0 ? _pool.Dequeue() : CreateNew();
   571→        obj.gameObject.SetActive(true);
   572→        return obj;
   573→    }
   574→
   575→    public void Return(T obj)
   576→    {
   577→        obj.gameObject.SetActive(false);
   578→        obj.transform.SetParent(_parent);
   579→        _pool.Enqueue(obj);
   580→    }
   581→
   582→    private T CreateNew()
   583→    {
   584→        return Object.Instantiate(_prefab, _parent);
   585→    }
   586→}
   587→```
