   640→## 资源管理规范
   641→
   642→### Addressables 使用规范
   643→
   644→```csharp
   645→public class AssetLoader : MonoBehaviour
   646→{
   647→    private readonly List<AsyncOperationHandle> _handles = new List<AsyncOperationHandle>();
   648→
   649→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
   650→    {
   651→        var handle = Addressables.LoadAssetAsync<T>(address);
   652→        await handle.Task;
   653→
   654→        if (handle.Status == AsyncOperationStatus.Succeeded)
   655→        {
   656→            _handles.Add(handle);
   657→            return handle.Result;
   658→        }
   659→
   660→        Debug.LogError($"Failed to load asset: {address}");
   661→        return null;
   662→    }
   663→
   664→    private void OnDestroy()
   665→    {
   666→        foreach (var handle in _handles)
   667→        {
   668→            Addressables.Release(handle);
   669→        }
   670→        _handles.Clear();
   671→    }
   672→}
   673→```
