public class PlayerInventory : MonoBehaviour { }

// ❌ 错误：单一组件承担过多职责
public class Player : MonoBehaviour
{
    public void Move() { }
    public void TakeDamage() { }
    public void AddItem() { }
    public void Attack() { }
