}
```

### 组件通信模式

```csharp
// 1. 直接引用 - 适用于紧耦合组件
public class PlayerController : MonoBehaviour
{
    [SerializeField] private PlayerHealth _health;

    public void TakeDamage(int damage)
    {
        _health?.Damage(damage);
